const LoadingPanel=()=> <section className="panel section-loading" aria-label="Загрузка раздела"><i/><i/><i/></section>;
const AuditPanel=dynamic(()=>import("./product-panels").then(module=>module.AuditPanel),{loading:LoadingPanel});
const TeamPanel=dynamic(()=>import("./product-panels").then(module=>module.TeamPanel),{loading:LoadingPanel});
const TasksPanel=dynamic(()=>import("./tasks-panel").then(module=>module.TasksPanel),{loading:LoadingPanel});
