type Row = Record<string, unknown> & { id: string; organization_id?: string };
type Data = { employees: Row[]; inventory: Row[]; ppe: Row[]; documents: Row[] };
type Kind = "employees" | "inventory" | "ppe" | "documents";
export type Tab = "overview" | "employees" | "tmc" | "documents" | "positions" | "tasks" | "learning" | "vision" | "team" | "audit" | "billing" | "admin";
export type DirectoryItem = {id:string;name:string;format?:string;is_active?:boolean};
type PaymentRequest = { id: string; organization_id: string; payment_reference?: string | null; status: string; created_at: string; organizations?: { name?: string; plan?: string; subscription_status?: string } | { name?: string; plan?: string; subscription_status?: string }[] | null };
type AdminOrganization = { id: string; name: string; plan: string; subscription_status: string; created_at: string };
export type AdminAccessUser = { organization_id:string; organization_name:string; user_id:string; full_name?:string|null; email?:string|null; role:string; is_active:boolean; created_at:string };
type Workspace = { id:string; name:string; role:string; plan:string; subscription_status:string; section_permissions?:SectionKey[] };
type Props = { demo?: boolean; initialTab?:Tab; supabaseUrl?: string; supabaseKey?: string; userEmail?: string; userId?:string; organizationId?: string; organizationName?: string; role?: string; plan?: string; initialData?: Data; configurationError?: string; isPlatformAdmin?: boolean; kaspiPayUrl?: string; paymentRequests?: PaymentRequest[]; adminOrganizations?: AdminOrganization[]; adminAccessUsers?:AdminAccessUser[]; workspaces?:Workspace[]; sectionPermissions?:SectionKey[]; tasks?:TaskItem[]; members?:TeamMember[]; auditEvents?:AuditEvent[]; learningCourses?:LearningCourse[]; learningAttempts?:LearningAttempt[]; learningAssignments?:LearningAssignment[]; visionCameras?:VisionCamera[]; visionEvents?:VisionEvent[]; jobProfiles?:JobProfile[]; notifications?:UserNotification[]; trainingTypes?:DirectoryItem[]; documentCategories?:DirectoryItem[] };

const nav: { id: Tab; label: string; icon: string }[] = [
  { id: "overview", label: "Оперативный центр", icon: "⌁" }, { id: "employees", label: "Работники", icon: "◯" },
  { id: "positions", label: "Должности", icon: "▦" },
  { id: "tmc", label: "ТМЦ", icon: "◇" },
  { id: "documents", label: "Документы", icon: "▤" }, { id:"tasks",label:"Задачи",icon:"✓" },
  { id:"learning",label:"Обучение",icon:"◫" }, { id:"vision",label:"Safety Vision",icon:"◎" },
  { id:"team",label:"Руководители",icon:"◌" }, { id:"audit",label:"Журнал действий",icon:"⌁" },
  { id: "billing", label: "Тариф и оплата", icon: "◫" },
];

const iso = (offset: number) => { const d = new Date(); d.setDate(d.getDate() + offset); return d.toISOString().slice(0, 10) };
const seed: Data = { employees: [
  { id: "e1", full_name: "Айдос Нурланов", department: "Техническая служба", position: "Электромонтёр", hire_date: iso(-430), medical_exam_expiry: iso(-3), briefing_expiry: iso(12), training_expiry: iso(74) },
  { id: "e2", full_name: "Алина Садыкова", department: "Лаборатория", position: "Инженер-химик", hire_date: iso(-210), medical_exam_expiry: iso(90), briefing_expiry: iso(4), training_expiry: iso(130) },
  { id: "e3", full_name: "Марат Ибраев", department: "Эксплуатация", position: "Техник", hire_date: iso(-95), medical_exam_expiry: iso(210), briefing_expiry: iso(170), training_expiry: iso(-9) },
], inventory: [
  { id: "i1", name: "Огнетушитель ОП-5 №118", category: "Пожарная безопасность", building: "Корпус A", location: "2 этаж", next_service_date: iso(7) },
  { id: "i2", name: "Пожарный кран ПК-14", category: "Пожарная безопасность", building: "Корпус B", location: "1 этаж", next_service_date: iso(-5) },
], ppe: [{ id: "p1", employee_name: "Айдос Нурланов", item_name: "Диэлектрические перчатки", quantity: 1, issued_at: iso(-200), replacement_date: iso(14) }], documents: [] };

function urgency(date?: string | number | null) { if (!date) return "red"; const days = Math.ceil((new Date(String(date)).getTime() - Date.now()) / 86400000); return days < 0 ? "red" : days <= 30 ? "yellow" : "green" }
type TrainingRecord={due_date?:string;next_due_at?:string;completed_at?:string;completed?:boolean};
function trainingRecords(e:Row){return(e.training_records&&typeof e.training_records==="object"&&!Array.isArray(e.training_records)?e.training_records:{}) as Record<string,TrainingRecord>}
function employeeStatus(e: Row) { const records=trainingRecords(e),codes=Array.isArray(e.required_training_codes)?e.required_training_codes.map(String):[];const values=[e.medical_exam_expiry].filter(Boolean).map(value=>urgency(typeof value==="string"||typeof value==="number"?value:null));for(const code of codes){const record=records[code];if(!record?.completed){values.push(record?.due_date?urgency(record.due_date):"red");continue}if(record.next_due_at)values.push(urgency(record.next_due_at))}return values.includes("red") ? "red" : values.includes("yellow") ? "yellow" : "green" }
function briefingLabel(e:Row){const primary=trainingRecords(e).primary_workplace;if(primary?.completed_at)return primary.next_due_at?`следующий ${formatDate(primary.next_due_at)}`:`пройден ${formatDate(primary.completed_at)}`;return primary?.due_date?formatDate(primary.due_date):"—"}
function formatDate(value: unknown) { if (!value) return "—"; return new Intl.DateTimeFormat("ru-RU").format(new Date(`${String(value).slice(0,10)}T00:00:00`)) }
function Status({ value }: { value: string }) { const label = value === "red" ? "Недопуск" : value === "yellow" ? "Скоро срок" : "В норме"; return <span className={`status ${value}`}>{label}</span> }
function PaymentStatus({ value }: { value: string }) { const tone=value==='approved'?'green':value==='pending'?'yellow':'red'; const label=value==='approved'?'Подтверждён':value==='pending'?'На проверке':'Отклонён'; return <span className={`status ${tone}`}>{label}</span> }

export function Dashboard({ demo = false, initialTab="overview", supabaseUrl = "", supabaseKey = "", userEmail = "developer@hseradar.kz", userId="", organizationId, organizationName = "HSE Radar Demo", role = "owner", plan = "free", initialData, configurationError, isPlatformAdmin = false, kaspiPayUrl = "", paymentRequests = [], adminOrganizations = [], adminAccessUsers=[], workspaces=[], sectionPermissions=[], tasks=[], members=[], auditEvents=[], learningCourses=[], learningAttempts=[], learningAssignments=[], visionCameras=[], visionEvents=[], jobProfiles=[],notifications=[],trainingTypes=[],documentCategories=[] }: Props) {
  const router=useRouter();
  const [tab, setTab] = useState<Tab>(initialTab); const [data, setData] = useState<Data>(initialData || seed); const [menu, setMenu] = useState(false);
  const [editor, setEditor] = useState<{ kind: Kind; item?: Row; category?: string } | null>(null); const [busy, setBusy] = useState(false); const [notice, setNotice] = useState(configurationError || ""); const [paymentReference, setPaymentReference] = useState("");
  const [importOpen,setImportOpen]=useState(false);const[documentOpen,setDocumentOpen]=useState(false);const[documentFile,setDocumentFile]=useState<File|null>(null);const[documentEditing,setDocumentEditing]=useState<Row|null>(null);const[categoryItems,setCategoryItems]=useState(documentCategories);const[quickAdd,setQuickAdd]=useState<"menu"|"task"|"learning"|null>(null);
  useEffect(() => { if (!demo) return; const saved = localStorage.getItem("hse-radar-next-demo"); if (saved) queueMicrotask(() => { try { setData(JSON.parse(saved)) } catch {} }); }, [demo]);
  useEffect(() => { if (demo) localStorage.setItem("hse-radar-next-demo", JSON.stringify(data)) }, [data, demo]);
  useEffect(()=>{document.body.classList.toggle("overlay-open",menu||Boolean(editor)||importOpen||documentOpen||Boolean(quickAdd));return()=>document.body.classList.remove("overlay-open")},[menu,editor,importOpen,documentOpen,quickAdd]);
  const sectionUrl=(section:Tab,org=organizationId)=>{const query=new URLSearchParams();if(org)query.set("org",org);query.set("section",section);return `/?${query.toString()}`};
  const go=(section:Tab,org=organizationId)=>{setMenu(false);if(demo){setTab(section);return}router.push(sectionUrl(section,org))};
  const canSection=(section:string)=>isPlatformAdmin||role==="owner"||sectionPermissions.includes(section as SectionKey)||(section==="tmc"&&(sectionPermissions.includes("inventory" as SectionKey)||sectionPermissions.includes("ppe" as SectionKey)));
  const hasUnlimitedAccess = isPlatformAdmin || !["trial","free"].includes(plan);
  const trialFull = (kind: Kind) => !hasUnlimitedAccess && (kind==="inventory"||kind==="ppe"?data.inventory.length+data.ppe.length:data[kind].length) >= 5;
  const openEditor = (kind: Kind, item?: Row, category?:string) => {
    if (!item && trialFull(kind)) return setNotice("Лимит Free исчерпан: максимум 5 записей в разделе. После подтверждения оплаты лимит снимается.");
    setEditor({ kind, item, category });
  };
  const risks = useMemo(() => data.employees.flatMap(e => {const base=[{id:`${e.id}-m`,date:String(e.medical_exam_expiry||""),title:String(e.full_name||""),detail:"Медосмотр"}];const records=trainingRecords(e),codes=Array.isArray(e.required_training_codes)?e.required_training_codes.map(String):[];const training=codes.flatMap(code=>{const record=records[code];const date=record?.completed?record.next_due_at:record?.due_date;return date?[{id:`${e.id}-training-${code}`,date:String(date),title:String(e.full_name||""),detail:trainingOptions.find(([value])=>value===code)?.[1]||code.replace(/^custom:/,"")}]:[]});return[...base,...training]}).filter(x => x.date&&urgency(x.date) !== "green").sort((a,b) => String(a.date).localeCompare(String(b.date))), [data.employees]);
  const extraDeadlines=useMemo(()=>[...data.inventory.map(item=>({id:`inventory-${item.id}`,title:String(item.name||"ТМЦ"),detail:String(item.category||"ТМЦ"),date:String(item.next_service_date||""),module:"tmc" as const})),...data.ppe.map(item=>({id:`ppe-${item.id}`,title:String(item.item_name||"СИЗ"),detail:String(item.employee_name||"Замена СИЗ"),date:String(item.replacement_date||""),module:"tmc" as const})),...data.documents.filter(item=>!item.is_perpetual&&(item.review_date||item.expires_at)).map(item=>({id:`document-${item.id}`,title:String(item.name||"Документ"),detail:"Пересмотр документа",date:String(item.review_date||item.expires_at||""),module:"documents" as const}))],[data.documents,data.inventory,data.ppe]);
  async function persist(kind: Kind, row: Row, update = false) {
    if (!update && trialFull(kind)) throw new Error("Лимит Free: максимум 5 записей в разделе.");
    if (demo) { setData(d => ({ ...d, [kind]: update ? d[kind].map(x => x.id === row.id ? row : x) : [...d[kind], row] })); return }
    const supabase = createClient(supabaseUrl, supabaseKey); const table = kind === "ppe" ? "ppe_issues" : kind;
    const result = update ? await supabase.from(table).update(row).eq("id", row.id).select().single() : await supabase.from(table).insert({ ...row, organization_id: organizationId }).select().single();
    if (result.error) throw result.error; const saved = result.data as Row; setData(d => ({ ...d, [kind]: update ? d[kind].map(x => x.id === row.id ? saved : x) : [...d[kind], saved] }));
  }
  async function remove(kind: Kind, id: string) { if (!confirm("Переместить запись в архив? История изменений сохранится.")) return; if (!demo) { const table = kind === "ppe" ? "ppe_issues" : kind; const { error } = await createClient(supabaseUrl, supabaseKey).rpc("archive_record",{target_table:table,target_id:id}); if (error) return setNotice(error.message) } setData(d => ({ ...d, [kind]: d[kind].filter(x => x.id !== id) })); }
  async function bulkRemove(kind:Kind,ids:string[]){if(!ids.length||!confirm(`Удалить выбранные записи (${ids.length})? История изменений сохранится.`))return false;setBusy(true);setNotice("");try{if(!demo){const table=kind==="ppe"?"ppe_issues":kind;const result=await createClient(supabaseUrl,supabaseKey).rpc("archive_records",{target_table:table,target_ids:ids});if(result.error)throw result.error}setData(current=>({...current,[kind]:current[kind].filter(item=>!ids.includes(item.id))}));setNotice(`Удалено записей: ${ids.length}.`);return true}catch(error){setNotice(error instanceof Error?error.message:"Не удалось удалить записи");return false}finally{setBusy(false)}}
  async function saveEditor(e: FormEvent<HTMLFormElement>) { e.preventDefault(); if (!editor) return; setBusy(true); setNotice(""); try { const form=new FormData(e.currentTarget);const v = Object.fromEntries(form); const old: Row = editor.item || { id: "" }; const row: Row = { ...old, ...v, id: old.id || crypto.randomUUID() }; if(editor.kind==="employees"){const profile=jobProfiles.find(x=>x.id===String(row.job_profile_id));row.position=profile?.title||String(row.position||"");row.briefing_interval_months=Number(form.get("briefing_interval_months")||6);row.briefing_expiry=String(old.briefing_expiry||"2099-12-31");row.training_expiry=String(old.training_expiry||"2099-12-31");(row as Record<string,unknown>).required_training_codes=form.getAll("required_training_codes").map(String);(row as Record<string,unknown>).training_records=JSON.parse(String(form.get("training_records")||"{}"))} if (editor.kind === "ppe"||editor.kind==="inventory") row.quantity = Number(row.quantity||1); await persist(editor.kind, row, Boolean(editor.item)); setEditor(null) } catch (err) { setNotice(err instanceof Error ? err.message : "Не удалось сохранить") } finally { setBusy(false) } }
  function chooseDocument(file:File|null){if(!file)return setDocumentFile(null);const allowed=["application/pdf","image/jpeg","image/png","application/vnd.openxmlformats-officedocument.wordprocessingml.document"];if(file.size>10*1024*1024||!allowed.includes(file.type)){setNotice("Разрешены PDF, JPG, PNG и DOCX размером до 10 МБ.");return}setDocumentFile(file)}
  function openDocument(item?:Row){if(!item&&trialFull("documents"))return setNotice("Лимит Free: максимум 5 документов.");setDocumentEditing(item||null);setDocumentFile(null);setDocumentOpen(true)}
  function closeDocument(){setDocumentOpen(false);setDocumentEditing(null);setDocumentFile(null)}
  async function uploadDocument(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget),perpetual=form.get("is_perpetual")==="on",metadata={name:String(form.get("name")||documentFile?.name||"Документ"),category:String(form.get("category")||"Внутренний документ"),review_date:perpetual?null:String(form.get("review_date")||"")||null,is_perpetual:perpetual};setBusy(true);try{if(documentEditing){await persist("documents",{...documentEditing,...metadata},true)}else{if(!documentFile)throw new Error("Выберите файл документа.");if(demo){await persist("documents",{id:crypto.randomUUID(),...metadata,storage_path:"demo",created_at:new Date().toISOString()})}else{const safeName=documentFile.name.replace(/[^a-zA-Zа-яА-Я0-9._-]/g,"_"),path=`${organizationId}/${crypto.randomUUID()}-${safeName}`,supabase=createClient(supabaseUrl,supabaseKey),uploaded=await supabase.storage.from("hse-documents").upload(path,documentFile);if(uploaded.error)throw uploaded.error;try{await persist("documents",{id:crypto.randomUUID(),...metadata,storage_path:path,created_at:new Date().toISOString()})}catch(error){await supabase.storage.from("hse-documents").remove([path]);throw error}}}closeDocument()}catch(err){setNotice(err instanceof Error?err.message:"Ошибка загрузки")}finally{setBusy(false)}}
  async function importEmployees(rows:ImportedEmployee[]){if(!hasUnlimitedAccess&&data.employees.length+rows.length>5)throw new Error(`Лимит Free: можно добавить ещё ${Math.max(0,5-data.employees.length)} работников.`);const prepared=rows.map(row=>({...row,id:crypto.randomUUID(),required_training_codes:["intro"]})) as Row[];if(demo){setData(current=>({...current,employees:[...current.employees,...prepared]}));return}const result=await createClient(supabaseUrl,supabaseKey).from("employees").insert(rows.map(row=>({...row,organization_id:organizationId,required_training_codes:["intro"],training_records:{}}))).select("*");if(result.error)throw result.error;setData(current=>({...current,employees:[...current.employees,...(result.data as Row[])]}));setNotice(`Импортировано работников: ${result.data.length}.`)}
  async function logout() { if (demo) return location.reload(); await createClient(supabaseUrl, supabaseKey).auth.signOut(); location.reload() }
  async function submitPaymentRequest() { if (!organizationId) return; if (!paymentReference.trim()) return setNotice("Укажите комментарий или номер платежа из Kaspi Pay."); setBusy(true); const { error } = await createClient(supabaseUrl, supabaseKey).from("payment_requests").insert({ organization_id: organizationId, payment_reference: paymentReference.trim() }); setBusy(false); if (error) return setNotice(error.message); setNotice("Заявка отправлена. Полный доступ включится после проверки платежа руководителем платформы."); setPaymentReference(""); location.reload() }
  async function reviewPayment(id: string, action: "approve" | "reject") { setBusy(true); const { error } = await createClient(supabaseUrl, supabaseKey).rpc(action === "approve" ? "approve_payment_request" : "reject_payment_request", { request_id:id }); setBusy(false); if (error) return setNotice(error.message); location.reload() }
  function openQuick(kind:"employees"|"inventory"|"ppe"|"documents"|"tasks"|"learning"){if(kind==="employees"||kind==="inventory"||kind==="ppe"){setQuickAdd(null);openEditor(kind)}else if(kind==="documents"){setQuickAdd(null);openDocument()}else setQuickAdd(kind==="tasks"?"task":"learning")}
  async function createQuickTask(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!organizationId)return;const form=new FormData(event.currentTarget);setBusy(true);setNotice("");const result=await createClient(supabaseUrl,supabaseKey).from("tasks").insert({organization_id:organizationId,title:String(form.get("title")),description:String(form.get("description")||""),priority:String(form.get("priority")||"medium"),due_date:String(form.get("due_date")),assignee_id:String(form.get("assignee_id")||"")||null,status:"open"}).select("id").single();setBusy(false);if(result.error)return setNotice(result.error.message);setQuickAdd(null);setNotice("Задача создана.");router.refresh()}
  async function createQuickLearning(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!organizationId)return;const form=new FormData(event.currentTarget),employeeIds=form.getAll("employee_ids").map(String),trainingType=String(form.get("training_type"));if(!employeeIds.length)return setNotice("Выберите хотя бы одного работника.");setBusy(true);setNotice("");const course=await createClient(supabaseUrl,supabaseKey).from("learning_courses").insert({organization_id:organizationId,title:trainingOptions.find(([code])=>code===trainingType)?.[1]||"Обучение",format:"briefing",training_type:trainingType,requires_test:false,course_type:"instruction",passing_score:80}).select("id").single();if(course.error){setBusy(false);return setNotice(course.error.message)}const assigned=await createClient(supabaseUrl,supabaseKey).from("learning_assignments").upsert(employeeIds.map(employee_id=>({organization_id:organizationId,course_id:course.data.id,employee_id,due_date:String(form.get("due_date"))})),{onConflict:"course_id,employee_id"});setBusy(false);if(assigned.error)return setNotice(assigned.error.message);setQuickAdd(null);setNotice(`Назначено обучение: ${employeeIds.length}.`);router.refresh()}
  return <div className="app-shell">
    {demo && <div className="demo-bar">ДЕМО-РЕЖИМ · данные сохраняются только в этом браузере</div>}
    {menu&&<button className="sidebar-dismiss" aria-label="Закрыть меню" onClick={()=>setMenu(false)}/>}
    <aside className={menu ? "sidebar open" : "sidebar"} onClick={event=>event.stopPropagation()}><RadarLogo onClick={()=>go("overview")}/><p className="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</p><nav>{[...nav,...(isPlatformAdmin?[{id:"admin" as Tab,label:"Управление платформой",icon:"◆"}]:[])].filter(n=>canSection(n.id)).map(n => <button type="button" key={n.id} className={tab === n.id ? "nav-item active" : "nav-item"} onPointerEnter={()=>{if(!demo)router.prefetch(sectionUrl(n.id))}} onFocus={()=>{if(!demo)router.prefetch(sectionUrl(n.id))}} onClick={() => go(n.id)}><span>{n.icon}</span>{n.label}</button>)}</nav><div className="account"><div className="avatar">{userEmail?.slice(0,2).toUpperCase()}</div><div><strong>{userEmail?.split("@")[0]}</strong><small>{isPlatformAdmin ? "Administrator" : plan === "pro" ? "Pro" : "Free"}</small></div><button type="button" onClick={logout} title="Выйти">↗</button></div></aside>
    <main className="workspace"><header><button type="button" className="mobile-menu" onClick={() => setMenu(true)}>☰</button><div>{workspaces.length>1?<select className="workspace-switcher" value={organizationId} onChange={e=>go("overview",e.target.value)}>{workspaces.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select>:<span className="header-org">{organizationName}</span>}<small>{demo ? "Локальное пространство" : "Защищено Supabase RLS"}</small></div><div className="header-actions"><NotificationCenter initial={notifications} organizationId={organizationId||""} supabaseUrl={supabaseUrl} supabaseKey={supabaseKey}/><LanguageSwitcher/></div></header>
      {notice && <div className="toast"><span>{notice}</span><button onClick={() => setNotice("")}>×</button></div>}
      {tab === "overview" && <OperationalOverview employeeCount={data.employees.length} risks={risks} extraDeadlines={extraDeadlines} tasks={tasks} assignments={learningAssignments} visionEvents={visionEvents} members={members} canOpen={canSection} add={() => setQuickAdd("menu")} open={(section) => go(section as Tab)} />}
      {tab === "employees" && <ListPage title="Работники" eyebrow="РЕЕСТР И ДОПУСКИ" addLabel="Добавить сотрудника" onAdd={() => openEditor("employees")} extra={<button className="button secondary" onClick={()=>setImportOpen(true)}>↑ Импорт из Excel</button>}><EmployeeTable rows={data.employees} busy={busy} edit={item => openEditor("employees",item)} remove={id => remove("employees",id)} bulkRemove={ids=>bulkRemove("employees",ids)} /></ListPage>}
      {tab === "positions" && organizationId && <PositionsPanel initial={jobProfiles} organizationId={organizationId} supabaseUrl={supabaseUrl} supabaseKey={supabaseKey}/>}
      {tab === "tmc" && <TmcPage inventory={data.inventory} ppe={data.ppe} busy={busy} add={(kind,category)=>openEditor(kind,undefined,category)} edit={(kind,item)=>openEditor(kind,item)} remove={remove} bulkRemove={bulkRemove}/>}
      {tab === "documents" && <ListPage title="Документы" eyebrow="ЕДИНОЕ ХРАНИЛИЩЕ" addLabel="Загрузить документ" onAdd={()=>openDocument()} extra={(role==="owner"||isPlatformAdmin)?<DirectoryManager title="Категории документов" table="document_categories" items={categoryItems} setItems={setCategoryItems} organizationId={organizationId||""} supabaseUrl={supabaseUrl} supabaseKey={supabaseKey}/>:undefined}><Documents rows={data.documents} busy={busy} edit={openDocument} remove={id => remove("documents",id)} bulkRemove={ids=>bulkRemove("documents",ids)} /></ListPage>}
      {tab === "tasks" && organizationId && <TasksPanel initial={tasks} members={members} currentUserId={userId} canManage={isPlatformAdmin||role==='owner'||role==='hse'||role==='manager'} organizationId={organizationId} supabaseUrl={supabaseUrl} supabaseKey={supabaseKey}/>}
      {tab === "learning" && organizationId && <LearningPanel organizationId={organizationId} supabaseUrl={supabaseUrl} supabaseKey={supabaseKey} initialCourses={learningCourses} initialAttempts={learningAttempts} initialAssignments={learningAssignments} employees={data.employees.map(item=>({id:item.id,full_name:String(item.full_name||""),department:item.department?String(item.department):null}))} customTypes={trainingTypes} canAdmin={role==="owner"||isPlatformAdmin}/>}
      {tab === "vision" && organizationId && <SafetyVisionPanel organizationId={organizationId} supabaseUrl={supabaseUrl} supabaseKey={supabaseKey} initialCameras={visionCameras} initialEvents={visionEvents}/>}
      {tab === "team" && organizationId && <TeamPanel initial={members} organizationId={organizationId} canAdmin={isPlatformAdmin||role==="owner"}/>}
      {tab === "audit" && <AuditPanel events={auditEvents} members={members}/>}
      {tab === "billing" && <Billing plan={plan} unlimited={hasUnlimitedAccess} isPlatformAdmin={isPlatformAdmin} data={data} kaspiPayUrl={kaspiPayUrl} paymentReference={paymentReference} setPaymentReference={setPaymentReference} submit={submitPaymentRequest} busy={busy} pending={paymentRequests.some(x=>x.organization_id===organizationId&&x.status==="pending")} />}
      {tab === "admin" && isPlatformAdmin && <AdminPanel organizations={adminOrganizations} requests={paymentRequests} accessUsers={adminAccessUsers} busy={busy} review={reviewPayment} />}
    </main>{editor && <Editor kind={editor.kind} item={editor.item} category={editor.category} busy={busy} close={() => setEditor(null)} save={saveEditor} employees={data.employees} jobProfiles={jobProfiles}/>}
    {importOpen&&<EmployeeImport close={()=>setImportOpen(false)} submit={importEmployees} limit={hasUnlimitedAccess?undefined:Math.max(0,5-data.employees.length)}/>}
    {documentOpen&&<DocumentUpload file={documentFile} item={documentEditing||undefined} categories={categoryItems} busy={busy} close={closeDocument} choose={chooseDocument} save={uploadDocument}/>}
    {quickAdd&&<QuickAddDialog mode={quickAdd} busy={busy} close={()=>setQuickAdd(null)} open={openQuick} createTask={createQuickTask} createLearning={createQuickLearning} employees={data.employees} members={members}/>}
    {busy&&<RadarLoader overlay/>}
  </div>;
}

function Metric({value,label,tone=""}:{value:number;label:string;tone?:string}) { return <div className={`metric ${tone}`}><b>{value}</b><span>{label}</span><i/></div> }
function QuickAddDialog({mode,busy,close,open,createTask,createLearning,employees,members}:{mode:"menu"|"task"|"learning";busy:boolean;close:()=>void;open:(kind:"employees"|"inventory"|"ppe"|"documents"|"tasks"|"learning")=>void;createTask:(event:FormEvent<HTMLFormElement>)=>void;createLearning:(event:FormEvent<HTMLFormElement>)=>void;employees:Row[];members:TeamMember[]}){
 const options:["employees"|"inventory"|"ppe"|"documents"|"tasks"|"learning",string,string][]=[["employees","Работник","Новая карточка сотрудника"],["inventory","ТМЦ","Инвентарь, приборы и материалы"],["ppe","СИЗ","Выдать средство защиты"],["documents","Документ","Загрузить файл в хранилище"],["tasks","Задача","Назначить действие и срок"],["learning","Обучение","Назначить обучение работникам"]];
 return <div className="modal-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)close()}}><section className="modal quick-add-modal"><div className="modal-head"><div><span className="eyebrow">ОПЕРАТИВНОЕ ДОБАВЛЕНИЕ</span><h2>{mode==="menu"?"Добавить":"Новая запись"}</h2></div><button type="button" onClick={close} aria-label="Закрыть">×</button></div>{mode==="menu"?<div className="quick-add-grid">{options.map(([kind,title,description])=><button type="button" key={kind} onClick={()=>open(kind)}><b>{title}</b><span>{description}</span><i>＋</i></button>)}</div>:mode==="task"?<form className="compact-form quick-add-form" onSubmit={createTask}><h3>Новая задача</h3><label>Что нужно сделать<input name="title" required autoFocus/></label><label>Описание<textarea name="description" rows={3}/></label><div className="form-grid"><label>Приоритет<select name="priority" defaultValue="medium"><option value="low">Низкий</option><option value="medium">Средний</option><option value="high">Высокий</option><option value="critical">Критический</option></select></label><label>Срок<input name="due_date" type="date" required/></label></div><label>Ответственный<select name="assignee_id"><option value="">Не назначен</option>{members.map(item=><option key={item.user_id} value={item.user_id}>{item.full_name||item.email||item.user_id.slice(0,8)}</option>)}</select></label><div className="modal-actions"><button type="button" className="button secondary" onClick={close}>Отмена</button><button className="button dark" disabled={busy}>{busy?"Сохранение…":"Создать задачу"}</button></div></form>:<form className="compact-form quick-add-form" onSubmit={createLearning}><h3>Назначить обучение</h3><label>Вид обучения<select name="training_type" defaultValue="intro">{trainingOptions.map(([code,label])=><option key={code} value={code}>{label}</option>)}</select></label><fieldset className="employee-picker"><legend>Работники</legend>{employees.map(employee=><label key={employee.id}><input type="checkbox" name="employee_ids" value={employee.id}/><span>{String(employee.full_name||"Сотрудник")}<small>{String(employee.department||"Без подразделения")}</small></span></label>)}</fieldset><label>Срок прохождения<input name="due_date" type="date" required/></label><div className="modal-actions"><button type="button" className="button secondary" onClick={close}>Отмена</button><button className="button dark" disabled={busy||!employees.length}>{busy?"Сохранение…":"Назначить"}</button></div></form>}</section></div>
}
function ListControls({query,setQuery,segments,value,setValue}:{query:string;setQuery:(value:string)=>void;segments:string[];value:string;setValue:(value:string)=>void}){return <div className="list-controls"><label className="list-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="5.5"/><path d="m15 15 5 5"/></svg><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Поиск" aria-label="Поиск по списку"/></label><div className="segmented-filter" role="group" aria-label="Фильтр списка">{segments.map(segment=><button type="button" className={segment===value?"active":""} key={segment} onClick={()=>setValue(segment)}>{segment}</button>)}</div></div>}
function ListPage({title,eyebrow,addLabel,onAdd,extra,children}:{title:string;eyebrow:string;addLabel:string;onAdd?:()=>void;extra?:React.ReactNode;children:React.ReactNode}) { return <><section className="page-heading compact"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1></div><div className="heading-actions">{extra}{addLabel && <button type="button" className="button dark" onClick={onAdd}>＋ {addLabel}</button>}</div></section>{children}</> }
const Actions=({item,edit,remove}:{item:Row;edit:(x:Row)=>void;remove:(id:string)=>void})=><div className="row-actions"><button type="button" className="icon-action" title="Изменить" aria-label="Изменить" onClick={()=>edit(item)}><PencilIcon title="Изменить"/></button><button type="button" className="danger-link icon-action" title="Удалить" aria-label="Удалить" onClick={()=>remove(item.id)}><TrashIcon title="Удалить"/></button></div>;
function EmployeeTable({rows,busy,edit,remove,bulkRemove}:{rows:Row[];busy:boolean;edit:(x:Row)=>void;remove:(id:string)=>void;bulkRemove:(ids:string[])=>Promise<boolean>}) {
  const[selected,setSelected]=useState<string[]>([]),[query,setQuery]=useState(""),[filter,setFilter]=useState("Все");const filtered=rows.filter(row=>{const match=`${row.full_name||""} ${row.department||""} ${row.position||""}`.toLocaleLowerCase().includes(query.toLocaleLowerCase());const status=employeeStatus(row);return match&&(filter==="Все"||filter==="Недопуск"&&status==="red"||filter==="Скоро срок"&&status==="yellow"||filter==="В норме"&&status==="green")});const all=Boolean(filtered.length)&&selected.length===filtered.length;
  const toggle=(id:string,checked:boolean)=>setSelected(value=>checked?[...new Set([...value,id])]:value.filter(item=>item!==id));
  async function removeSelected(){if(await bulkRemove(selected))setSelected([])}
  return <section className="panel table-panel"><ListControls query={query} setQuery={setQuery} segments={["Все","Недопуск","Скоро срок","В норме"]} value={filter} setValue={setFilter}/><BulkActions count={selected.length} allSelected={all} onToggleAll={()=>setSelected(all?[]:filtered.map(item=>item.id))} onClear={()=>setSelected([])} onDelete={removeSelected} busy={busy}/>{filtered.length?<table><thead><tr><th className="select-column"><SelectBox checked={all} onChange={checked=>setSelected(checked?filtered.map(item=>item.id):[])} label="Выбрать всех работников"/></th><th>Статус</th><th>Ф.И.О.</th><th>Подразделение</th><th>Должность</th><th>Инструктаж</th><th></th></tr></thead><tbody>{filtered.map(x=><tr key={x.id} className={selected.includes(x.id)?"is-selected":""}><td className="select-column"><SelectBox checked={selected.includes(x.id)} onChange={checked=>toggle(x.id,checked)} label={`Выбрать ${String(x.full_name||"работника")}`}/></td><td><Status value={employeeStatus(x)}/></td><td><strong>{String(x.full_name||"")}</strong></td><td>{String(x.department||"—")}</td><td>{String(x.position||"—")}</td><td>{briefingLabel(x)}</td><td><Actions item={x} edit={edit} remove={remove}/></td></tr>)}</tbody></table>:<Empty text={rows.length?"Ничего не найдено":"Работники ещё не добавлены"}/>}</section>
}
const tmcCategories=["СИЗ","Медицинское обеспечение","Пожарный инвентарь","Приборы","Информационные материалы"] as const;
function TmcPage({inventory,ppe,busy,add,edit,remove,bulkRemove}:{inventory:Row[];ppe:Row[];busy:boolean;add:(kind:"inventory"|"ppe",category:string)=>void;edit:(kind:"inventory"|"ppe",item:Row)=>void;remove:(kind:Kind,id:string)=>void;bulkRemove:(kind:Kind,ids:string[])=>Promise<boolean>}){
  const rows=[...inventory.map(item=>({...item,_kind:"inventory" as const,display_name:item.name,date:String(item.next_service_date||"")})),...ppe.map(item=>({...item,_kind:"ppe" as const,category:"СИЗ",display_name:item.item_name,date:String(item.replacement_date||"")}))] as Array<Row&{_kind:"inventory"|"ppe";display_name:Row[string];date:string}>;
  const[selected,setSelected]=useState<string[]>([]),[query,setQuery]=useState(""),[filter,setFilter]=useState("Все");const filtered=rows.filter(item=>{const match=`${item.display_name||""} ${item.category||""} ${item.building||""} ${item.location||""} ${item.employee_name||""}`.toLocaleLowerCase().includes(query.toLocaleLowerCase());return match&&(filter==="Все"||String(item.category||"")===filter)});const keys=filtered.map(item=>`${item._kind}:${item.id}`),all=Boolean(keys.length)&&selected.length===keys.length;
  const toggle=(key:string,checked:boolean)=>setSelected(value=>checked?[...new Set([...value,key])]:value.filter(item=>item!==key));
  async function removeSelected(){const inventoryIds=selected.filter(key=>key.startsWith("inventory:")).map(key=>key.slice(10)),ppeIds=selected.filter(key=>key.startsWith("ppe:")).map(key=>key.slice(4));let ok=true;if(inventoryIds.length)ok=(await bulkRemove("inventory",inventoryIds))&&ok;if(ppeIds.length)ok=(await bulkRemove("ppe",ppeIds))&&ok;if(ok)setSelected([])}
  return <><section className="page-heading compact"><div><span className="eyebrow">УЧЁТ И КОНТРОЛЬ</span><h1>ТМЦ</h1><p>Единый реестр материальных ценностей, выдачи и сроков обслуживания.</p></div></section><section className="tmc-categories">{tmcCategories.map((category,index)=>{const count=category==="СИЗ"?ppe.length:inventory.filter(item=>item.category===category).length;return <button type="button" key={category} onClick={()=>add(category==="СИЗ"?"ppe":"inventory",category)}><i>{["⬡","＋","◇","⌁","▤"][index]}</i><span><strong>{category}</strong><small>{count} записей</small></span><b>＋</b></button>})}</section><section className="panel table-panel"><ListControls query={query} setQuery={setQuery} segments={["Все",...tmcCategories]} value={filter} setValue={setFilter}/><BulkActions count={selected.length} allSelected={all} onToggleAll={()=>setSelected(all?[]:keys)} onClear={()=>setSelected([])} onDelete={removeSelected} busy={busy}/>{filtered.length?<table><thead><tr><th className="select-column"><SelectBox checked={all} onChange={checked=>setSelected(checked?keys:[])} label="Выбрать все ТМЦ"/></th><th>Статус</th><th>Наименование</th><th>Классификация</th><th>Размещение / получатель</th><th>Следующий срок</th><th></th></tr></thead><tbody>{filtered.map(item=>{const key=`${item._kind}:${item.id}`;return <tr key={key} className={selected.includes(key)?"is-selected":""}><td className="select-column"><SelectBox checked={selected.includes(key)} onChange={checked=>toggle(key,checked)} label={`Выбрать ${String(item.display_name||"ТМЦ")}`}/></td><td><Status value={urgency(item.date)}/></td><td><strong>{String(item.display_name||"")}</strong></td><td>{String(item.category||"—")}</td><td>{item._kind==="ppe"?`${item.employee_name||"—"} · ${item.department||"—"}`:`${item.building||"—"} · ${item.location||"—"}`}</td><td>{formatDate(item.date)}</td><td><Actions item={item} edit={row=>edit(item._kind,row)} remove={id=>remove(item._kind,id)}/></td></tr>})}</tbody></table>:<Empty text={rows.length?"Ничего не найдено":"ТМЦ ещё не добавлены"}/>}</section></>;
}
function Documents({rows,busy,edit,remove,bulkRemove}:{rows:Row[];busy:boolean;edit:(item:Row)=>void;remove:(id:string)=>void;bulkRemove:(ids:string[])=>Promise<boolean>}) { const[selected,setSelected]=useState<string[]>([]),all=Boolean(rows.length)&&selected.length===rows.length;const toggle=(id:string,checked:boolean)=>setSelected(value=>checked?[...new Set([...value,id])]:value.filter(item=>item!==id));async function removeSelected(){if(await bulkRemove(selected))setSelected([])}return <section className="panel document-grid"><BulkActions count={selected.length} allSelected={all} onToggleAll={()=>setSelected(all?[]:rows.map(item=>item.id))} onClear={()=>setSelected([])} onDelete={removeSelected} busy={busy}/>{rows.length?rows.map(x=><article className={`document ${selected.includes(x.id)?"is-selected":""}`} key={x.id}><SelectBox checked={selected.includes(x.id)} onChange={checked=>toggle(x.id,checked)} label={`Выбрать ${String(x.name||"документ")}`}/><span>FILE</span><div><a href={`/api/documents/${x.id}`} target="_blank" rel="noreferrer"><strong>{String(x.name||"")}</strong></a><small>{String(x.category||"")} · {x.is_perpetual?"Бессрочный":x.review_date?`пересмотр ${formatDate(x.review_date)}`:formatDate(x.created_at)}</small></div><div className="document-actions"><button type="button" title="Изменить" onClick={()=>edit(x)}>✎</button><button type="button" title="В архив" onClick={()=>remove(x.id)}>×</button></div></article>):<Empty text="Загрузите первый документ"/>}</section> }
function DocumentUpload({file,item,categories,busy,close,choose,save}:{file:File|null;item?:Row;categories:DirectoryItem[];busy:boolean;close:()=>void;choose:(file:File|null)=>void;save:(event:FormEvent<HTMLFormElement>)=>void}){const[perpetual,setPerpetual]=useState(Boolean(item?.is_perpetual));const defaults=["Внутренний документ","Инструкция","Приказ","Положение","Акт","Удостоверение"];const options=[...new Set([...defaults,...categories.filter(x=>x.is_active!==false).map(x=>x.name),String(item?.category||"")].filter(Boolean))];return <div className="modal-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)close()}}><form className="modal document-modal" onSubmit={save}><div className="modal-head"><div><span className="eyebrow">{item?"РЕДАКТИРОВАНИЕ":"НОВЫЙ ДОКУМЕНТ"}</span><h2>{item?String(item.name||"Документ"):"Загрузить документ"}</h2></div><button type="button" onClick={close}>×</button></div><div className="form-grid">{!item&&<label className="wide">Файл<input type="file" required accept=".pdf,.jpg,.jpeg,.png,.docx" onChange={event=>choose(event.target.files?.[0]||null)}/><small>{file?.name||"PDF, JPG, PNG или DOCX · до 10 МБ"}</small></label>}<Field name="name" label="Название документа" value={item?.name||file?.name||""} wide/><label className="wide">Категория<select name="category" defaultValue={String(item?.category||options[0])}>{options.map(name=><option key={name}>{name}</option>)}</select></label><label>Дата пересмотра<input name="review_date" type="date" defaultValue={String(item?.review_date||"").slice(0,10)} required={!perpetual} disabled={perpetual}/></label><label className="toggle-field">Бессрочный<span><input name="is_perpetual" type="checkbox" checked={perpetual} onChange={event=>setPerpetual(event.target.checked)}/><i/></span></label></div><div className="modal-actions"><button type="button" className="button secondary" onClick={close}>Отмена</button><button className="button dark" disabled={busy||(!item&&!file)}>{busy?"Сохранение…":item?"Сохранить":"Загрузить документ"}</button></div></form></div>}

function DirectoryManager({title,table,items,setItems,organizationId,supabaseUrl,supabaseKey}:{title:string;table:"document_categories";items:DirectoryItem[];setItems:React.Dispatch<React.SetStateAction<DirectoryItem[]>>;organizationId:string;supabaseUrl:string;supabaseKey:string}){const[open,setOpen]=useState(false),[busy,setBusy]=useState(false),[editing,setEditing]=useState<DirectoryItem|null>(null);async function save(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget),name=String(form.get("name")||"").trim();if(!name)return;setBusy(true);const db=createClient(supabaseUrl,supabaseKey);const result=editing?await db.from(table).update({name}).eq("id",editing.id).select().single():await db.from(table).insert({organization_id:organizationId,name}).select().single();setBusy(false);if(result.error)return alert(result.error.message);setItems(current=>editing?current.map(item=>item.id===editing.id?result.data as DirectoryItem:item):[...(current||[]),result.data as DirectoryItem]);setEditing(null);event.currentTarget.reset()}async function remove(item:DirectoryItem){setBusy(true);const result=await createClient(supabaseUrl,supabaseKey).from(table).delete().eq("id",item.id).select("id").maybeSingle();setBusy(false);if(result.error)return alert(result.error.message);if(!result.data)return alert("Категория не удалена: проверьте права доступа.");setItems(current=>current.filter(value=>value.id!==item.id))}return <><button type="button" className="button secondary" onClick={()=>setOpen(true)}>Настроить категории</button>{open&&<div className="modal-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)setOpen(false)}}><section className="modal directory-modal"><div className="modal-head"><div><span className="eyebrow">СПРАВОЧНИК</span><h2>{title}</h2></div><button type="button" onClick={()=>setOpen(false)}>×</button></div><form className="directory-form" onSubmit={save}><input name="name" required key={editing?.id||"new"} defaultValue={editing?.name||""} placeholder="Название категории"/><button className="button dark" disabled={busy}>{editing?"Сохранить":"Добавить"}</button></form><div className="directory-list">{items.map(item=><div key={item.id}><span>{item.name}</span><button type="button" onClick={()=>setEditing(item)}>Изменить</button><button type="button" className="danger-link" onClick={()=>remove(item)}>Удалить</button></div>)}</div></section></div>}</>}
function Empty({text}:{text:string}) { return <div className="empty"><div>⌁</div><strong>{text}</strong><span>Здесь появятся рабочие записи организации.</span></div> }
function Billing({plan,unlimited,isPlatformAdmin,data,kaspiPayUrl,paymentReference,setPaymentReference,submit,busy,pending}:{plan:string;unlimited:boolean;isPlatformAdmin:boolean;data:Data;kaspiPayUrl:string;paymentReference:string;setPaymentReference:(v:string)=>void;submit:()=>void;busy:boolean;pending:boolean}) { const usage=[['Работники',data.employees.length],['ТМЦ',data.ppe.length+data.inventory.length],['Документы',data.documents.length]] as const; return <><section className="page-heading compact"><div><span className="eyebrow">ПОДПИСКА</span><h1>Тариф и оплата</h1></div></section><section className="billing-grid"><article className="plan-card"><span className="eyebrow">HSE RADAR PRO</span><h2>Вся система.<br/>Без ограничений.</h2><ul><li>Без лимитов на рабочие записи</li><li>Допуски, ТМЦ и оборудование</li><li>Хранилище документов</li><li>Роли и защищённый доступ</li></ul>{unlimited?<div className="active-plan">✓ {isPlatformAdmin?'Полный доступ Platform Admin':'Полный доступ активен'}</div>:<>{kaspiPayUrl?<a className="button lime wide" href={kaspiPayUrl} target="_blank" rel="noreferrer">Оплатить через Kaspi Pay</a>:<div className="billing-warning">Ссылка Kaspi Pay ещё не добавлена разработчиком.</div>}<label className="payment-reference">Комментарий или номер платежа<input value={paymentReference} onChange={e=>setPaymentReference(e.target.value)} placeholder="Например: HSE Radar · Компания" /></label><button className="button secondary wide" disabled={busy||pending} onClick={submit}>{pending?'Платёж проверяется':busy?'Отправка…':'Я оплатил — отправить на проверку'}</button></>}</article><article className="panel"><span className="eyebrow">ТЕКУЩИЙ СТАТУС</span><h3>{isPlatformAdmin?'Доступ администратора':plan === "pro" ? "Подписка активна" : "Free: до 5 записей"}</h3><p className="muted">{unlimited?'Ограничения Free не применяются к этому аккаунту.':'Лимит действует отдельно для каждого раздела и контролируется базой данных, а не только интерфейсом.'}</p><div className="usage-grid">{usage.map(([label,value])=><div key={label}><span>{label}</span><strong>{value} / {unlimited?'∞':5}</strong><i><b style={{width:unlimited?'100%':`${Math.min(value/5*100,100)}%`}}/></i></div>)}</div></article></section></> }

function AdminPanel({organizations,requests,accessUsers,busy,review}:{organizations:AdminOrganization[];requests:PaymentRequest[];accessUsers:AdminAccessUser[];busy:boolean;review:(id:string,action:'approve'|'reject')=>void}) { const[users,setUsers]=useState(accessUsers),[accessBusy,setAccessBusy]=useState("");const orgName=(r:PaymentRequest)=>{const o=Array.isArray(r.organizations)?r.organizations[0]:r.organizations;return o?.name||r.organization_id};async function toggleAccess(item:AdminAccessUser){setAccessBusy(item.organization_id+item.user_id);const response=await fetch("/api/admin/access",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({organizationId:item.organization_id,userId:item.user_id,active:!item.is_active})}),body=await response.json();setAccessBusy("");if(!response.ok)return alert(body.error||"Не удалось изменить доступ");setUsers(rows=>rows.map(row=>row.organization_id===item.organization_id&&row.user_id===item.user_id?{...row,is_active:!item.is_active}:row))}return <><section className="page-heading compact"><div><span className="eyebrow">PLATFORM ADMIN</span><h1>Управление платформой</h1><p>Активация пользователей, организаций и платежей.</p></div></section><div className="admin-metrics"><Metric value={organizations.length} label="Организаций"/><Metric value={users.filter(x=>x.is_active).length} label="Активных пользователей"/><Metric value={requests.filter(x=>x.status==='pending').length} label="Платежей на проверке" tone="yellow"/></div><section className="panel table-panel admin-access-table"><div className="panel-title"><div><span className="eyebrow">ДОСТУП</span><h3>Пользователи платформы</h3></div></div>{users.length?<table><thead><tr><th>Пользователь</th><th>Организация</th><th>Роль</th><th>Состояние</th><th></th></tr></thead><tbody>{users.map(item=><tr key={item.organization_id+item.user_id}><td><strong>{item.full_name||item.email||item.user_id.slice(0,8)}</strong><small className="sub-id">{item.email||item.user_id.slice(0,8)}</small></td><td>{item.organization_name}</td><td>{item.role}</td><td><span className={`status ${item.is_active?'green':'red'}`}>{item.is_active?'Активен':'Отключён'}</span></td><td><button className={`access-toggle ${item.is_active?'danger':''}`} disabled={accessBusy===item.organization_id+item.user_id} onClick={()=>toggleAccess(item)}>{accessBusy===item.organization_id+item.user_id?'Сохранение…':item.is_active?'Отключить':'Активировать'}</button></td></tr>)}</tbody></table>:<Empty text="Пользователей пока нет"/>}</section><section className="panel table-panel admin-payment-table"><div className="panel-title"><div><span className="eyebrow">KASPI PAY</span><h3>Заявки на активацию</h3></div></div>{requests.length?<table><thead><tr><th>Организация</th><th>Комментарий</th><th>Дата</th><th>Статус</th><th></th></tr></thead><tbody>{requests.map(r=><tr key={r.id}><td><strong>{orgName(r)}</strong></td><td>{r.payment_reference||'—'}</td><td>{formatDate(r.created_at)}</td><td><PaymentStatus value={r.status}/></td><td>{r.status==='pending'&&<div className="row-actions"><button disabled={busy} onClick={()=>review(r.id,'approve')}>Подтвердить</button><button disabled={busy} className="danger-link" onClick={()=>review(r.id,'reject')}>Отклонить</button></div>}</td></tr>)}</tbody></table>:<Empty text="Заявок на оплату пока нет"/>}</section></> }

function Editor({kind,item,category,busy,close,save,employees,jobProfiles}:{kind:Kind;item?:Row;category?:string;busy:boolean;close:()=>void;save:(e:FormEvent<HTMLFormElement>)=>void;employees:Row[];jobProfiles:JobProfile[]}) {
 const titles={employees:"Сотрудник",inventory:"ТМЦ",ppe:"ТМЦ · СИЗ",documents:"Документ"};const departments=[...new Set(employees.map(e=>String(e.department||"")).filter(Boolean))];const initialCodes=String(item?.required_training_codes||"intro").split(",").filter(Boolean);
 const rawRecords=(item as unknown as {training_records?:Record<string,TrainingRecord>})?.training_records||{};
 const[selectedProfile,setSelectedProfile]=useState(String(item?.job_profile_id||"")),[codes,setCodes]=useState<string[]>(initialCodes.includes("intro")?initialCodes:["intro",...initialCodes]),[records,setRecords]=useState<Record<string,TrainingRecord>>(rawRecords),[dateCode,setDateCode]=useState<string|null>(null),[briefingInterval,setBriefingInterval]=useState(Number(item?.briefing_interval_months||6));
 const customOptions=[...new Set(jobProfiles.flatMap(profile=>[...(profile.custom_training_names||[]),...(profile.required_training_codes||[]).filter(code=>code.startsWith("custom:")).map(code=>code.slice(7))]).filter(Boolean))].map(name=>[`custom:${name}`,name] as const);
 const availableTrainingOptions=[...trainingOptions,...customOptions] as ReadonlyArray<readonly [string,string]>;
 function chooseProfile(id:string){setSelectedProfile(id);const p=jobProfiles.find(x=>x.id===id);if(p)setCodes([...new Set(["intro",...p.required_training_codes])])}
 function updateRecord(code:string,patch:TrainingRecord){setRecords(value=>({...value,[code]:{...value[code],...patch}}))}
 function addMonths(value:string,months:number){const date=new Date(`${value}T00:00:00`);date.setMonth(date.getMonth()+months);return date.toISOString().slice(0,10)}
 function markCompleted(code:string,completed:boolean){if(!completed)return updateRecord(code,{completed:false,completed_at:"",next_due_at:""});const completedAt=new Date().toISOString().slice(0,10),nextDue=code==="primary_workplace"?addMonths(completedAt,Math.max(1,briefingInterval)):records[code]?.next_due_at;updateRecord(code,{completed:true,completed_at:completedAt,next_due_at:nextDue,due_date:""})}
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="modal employee-editor" onSubmit={save}><div className="modal-head"><div><span className="eyebrow">{item?"РЕДАКТИРОВАНИЕ":"НОВАЯ ЗАПИСЬ"}</span><h2>{titles[kind]}</h2></div><button type="button" onClick={close}>×</button></div><div className="form-grid">{kind==="employees"&&<><Field name="full_name" label="Ф.И.О." value={item?.full_name} wide/><Field name="department" label="Подразделение" value={item?.department}/><label>Должность<select name="job_profile_id" value={selectedProfile} onChange={e=>chooseProfile(e.target.value)} required><option value="">Выберите карточку</option>{jobProfiles.map(p=><option key={p.id} value={p.id}>{p.title}</option>)}</select></label><Field name="hire_date" label="Дата приёма" type="date" value={item?.hire_date}/><Field name="medical_exam_expiry" label="Медосмотр до" type="date" value={item?.medical_exam_expiry}/><label>Периодичность инструктирования, мес.<input name="briefing_interval_months" type="number" min="1" max="60" value={briefingInterval} onChange={event=>setBriefingInterval(Number(event.target.value)||1)} required/></label><input type="hidden" name="training_records" value={JSON.stringify(records)}/><fieldset className="training-control wide"><legend>Необходимые обучения и прохождение</legend>{availableTrainingOptions.map(([value,label])=><div className={codes.includes(value)?"active":""} key={value}><label className="training-required"><input type="checkbox" name="required_training_codes" value={value} checked={codes.includes(value)} disabled={value==="intro"} onChange={()=>setCodes(current=>current.includes(value)?current.filter(code=>code!==value):[...current,value])}/><span>{label}</span></label><button type="button" disabled={!codes.includes(value)} onClick={()=>setDateCode(value)}>{records[value]?.next_due_at?`следующий ${formatDate(records[value].next_due_at)}`:records[value]?.completed_at?`пройден ${formatDate(records[value].completed_at)}`:records[value]?.due_date?formatDate(records[value].due_date):"Назначить дату"}</button><label className="mini-toggle" title="Отметить обучение пройденным"><input type="checkbox" checked={Boolean(records[value]?.completed)} disabled={!codes.includes(value)} onChange={event=>markCompleted(value,event.target.checked)}/><i/><span>Пройдено</span></label></div>)}</fieldset></>}{kind==="inventory"&&<><Field name="name" label="Наименование" value={item?.name} wide/><label>Классификация<select name="category" defaultValue={String(item?.category||category||tmcCategories[1])} required>{tmcCategories.filter(value=>value!=="СИЗ").map(value=><option key={value}>{value}</option>)}</select></label><Field name="quantity" label="Количество" type="number" value={item?.quantity||1}/><Field name="building" label="Здание" value={item?.building}/><Field name="location" label="Место" value={item?.location}/><Field name="next_service_date" label="Следующий контроль / обслуживание" type="date" value={item?.next_service_date}/></>}{kind==="ppe"&&<><label className="wide">Работник<select name="employee_name" defaultValue={String(item?.employee_name||"")} required><option value="">Выберите</option>{employees.map(e=><option key={e.id}>{String(e.full_name||"")}</option>)}</select></label><label>Структурное подразделение<select name="department" defaultValue={String(item?.department||"")} required><option value="">Выберите</option>{departments.map(d=><option key={d}>{d}</option>)}</select></label><Field name="item_name" label="Наименование СИЗ" value={item?.item_name}/><Field name="quantity" label="Количество" type="number" value={item?.quantity||1}/><Field name="issued_at" label="Дата выдачи" type="date" value={item?.issued_at}/><Field name="replacement_date" label="Дата замены" type="date" value={item?.replacement_date}/></>}</div><div className="modal-actions"><button type="button" className="button secondary" onClick={close}>Отмена</button><button className="button dark" disabled={busy}>{busy?"Сохранение…":"Сохранить"}</button></div>{dateCode&&<div className="nested-modal-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)setDateCode(null)}}><section className="date-modal"><strong>{availableTrainingOptions.find(([value])=>value===dateCode)?.[1]||dateCode.replace(/^custom:/,"")}</strong><label>Дата следующего прохождения<input type="date" value={records[dateCode]?.next_due_at||records[dateCode]?.due_date||""} onChange={event=>updateRecord(dateCode,{next_due_at:event.target.value,due_date:""})}/></label><div><button type="button" className="button secondary" onClick={()=>updateRecord(dateCode,{next_due_at:"",due_date:""})}>Без повторения</button><button type="button" className="button dark" onClick={()=>setDateCode(null)}>Готово</button></div></section></div>}</form></div>
}
function Field({name,label,type="text",value,wide=false,required=true}:{name:string;label:string;type?:string;value:unknown;wide?:boolean;required?:boolean}) { return <label className={wide?"wide":""}>{label}<input name={name} type={type} defaultValue={value==null?"":String(value).slice(0,type==="date"?10:undefined)} required={required} /></label> }
